import Foundation
import Security

// Vertical-slice tests for the imported-identity bootstrap path. Fixtures are
// synthetic PKCS#12 identities generated by the wrapper script (argv[1] = dir).
// Nothing here is a real Apple identity; no private key or password is logged.

var failures = 0
func check(_ cond: Bool, _ name: String) {
	if cond { print("PASS: \(name)") } else { failures += 1; print("FAIL: \(name)") }
}

let dir = CommandLine.arguments.count > 1 ? CommandLine.arguments[1] : "."
func data(_ f: String) -> Data { (try? Data(contentsOf: URL(fileURLWithPath: "\(dir)/\(f)"))) ?? Data() }

let team = "V54K5JYGS4"
let now = Date()
let farFuture = Date(timeIntervalSinceNow: 10 * 365 * 86_400)

// Import: correct vs wrong password.
let imported = ZagImportedSigningIdentity.importIdentity(pkcs12: data("id.p12"), password: "correct-horse")
check({ if case .success = imported { return true }; return false }(), "import synthetic PKCS#12 with correct password")
check({ if case .failure(.wrongPasswordOrCorrupt) = ZagImportedSigningIdentity.importIdentity(pkcs12: data("id.p12"), password: "nope") { return true }; return false }(),
	  "wrong password -> wrongPasswordOrCorrupt")
check({ if case .failure(.wrongPasswordOrCorrupt) = ZagImportedSigningIdentity.importIdentity(pkcs12: Data([0,1,2,3]), password: "x") { return true }; return false }(),
	  "corrupt data -> wrongPasswordOrCorrupt")

guard case .success(let id) = imported else {
	print("FAILURES: \(failures + 1)  (could not import primary fixture)")
	exit(1)
}

// Validation: correspondence + development suitability + team + validity window.
switch ZagImportedSigningIdentity.validate(id, now: now, expectedTeam: team) {
case .success(let info):
	check(info.team == team, "validate: team (OU) is the expected team")
	check(info.isDevelopment, "validate: recognised as a development certificate")
	check(info.isNonExtractable == false, "imported identity is NOT marked non-extractable")
	check(info.notAfter > now, "validate: certificate is within its validity window")
	check(!info.serialNumber.isEmpty, "validate: serial parsed")
case .failure(let e):
	check(false, "validate should succeed on the primary fixture (got \(e))")
}

// Expired: evaluated at a time past notAfter.
check({ if case .failure(.certExpired) = ZagImportedSigningIdentity.validate(id, now: farFuture, expectedTeam: team) { return true }; return false }(),
	  "expired certificate -> certExpired")
// Team mismatch.
check({ if case .failure(.teamMismatch) = ZagImportedSigningIdentity.validate(id, now: now, expectedTeam: "WRONGTEAM0") { return true }; return false }(),
	  "wrong expected team -> teamMismatch")

// Non-development certificate rejected.
if case .success(let server) = ZagImportedSigningIdentity.importIdentity(pkcs12: data("server.p12"), password: "pw3") {
	check({ if case .failure(.notDevelopmentCertificate) = ZagImportedSigningIdentity.validate(server, now: now) { return true }; return false }(),
		  "non-development certificate -> notDevelopmentCertificate")
} else { check(false, "import server.p12 fixture") }

// Correspondence: a different identity's certificate must not verify this key.
if case .success(let other) = ZagImportedSigningIdentity.importIdentity(pkcs12: data("id2.p12"), password: "pw2") {
	var c1: SecCertificate?; SecIdentityCopyCertificate(id, &c1)
	var k1: SecKey?; SecIdentityCopyPrivateKey(id, &k1)
	var c2: SecCertificate?; SecIdentityCopyCertificate(other, &c2)
	check(ZagImportedSigningIdentity.corresponds(key: k1!, certificate: c1!), "corresponds: key matches its own certificate")
	check(!ZagImportedSigningIdentity.corresponds(key: k1!, certificate: c2!), "corresponds: key does NOT match a different certificate")
	// Team mismatch is enforced against id2's different team as well.
	check({ if case .failure(.teamMismatch) = ZagImportedSigningIdentity.validate(other, now: now, expectedTeam: team) { return true }; return false }(),
		  "second identity's different team -> teamMismatch against expected team")
	// A signature from id must not verify under id2.
	let payload = Data("zag-test-payload".utf8)
	if let sig = ZagImportedSigningIdentity.sign(payload, identity: id) {
		check(!ZagImportedSigningIdentity.verify(sig, payload: payload, identity: other), "signature from one identity does not verify under another")
	}
} else { check(false, "import id2.p12 fixture") }

// Sign / verify round-trip with the imported key.
let payload = Data("the quick brown fox".utf8)
if let sig = ZagImportedSigningIdentity.sign(payload, identity: id) {
	check(ZagImportedSigningIdentity.verify(sig, payload: payload, identity: id), "sign then verify round-trip succeeds")
	check(!ZagImportedSigningIdentity.verify(sig, payload: Data("tampered".utf8), identity: id), "verify rejects a tampered payload")
} else { check(false, "sign a payload with the imported key") }

// Zsign callback: the SAME raw PKCS#1 v1.5 DigestInfo signer the device path uses.
// A SHA-256 DigestInfo is 19 header bytes + 32 hash bytes = 51 bytes; RSA-2048
// produces a 256-byte signature.
if let signer = ZagImportedSigningIdentity.zsignSigner(id) {
	let sha256DigestInfoPrefix = Data([0x30,0x31,0x30,0x0d,0x06,0x09,0x60,0x86,0x48,0x01,0x65,0x03,0x04,0x02,0x01,0x05,0x00,0x04,0x20])
	let digestInfo = sha256DigestInfoPrefix + Data(repeating: 0xAB, count: 32)
	let sig = signer(digestInfo)
	check(sig != nil, "zsign callback produces a signature")
	check(sig?.count == 256, "zsign signature is RSA-2048 sized (256 bytes)")
} else { check(false, "obtain zsign signer from imported identity") }

print(failures == 0 ? "ALL PASS" : "FAILURES: \(failures)")
exit(failures == 0 ? 0 : 1)
